1	import { getDrains } from '../../clever-client/drains.js';
2	import { defineCommand } from '../../lib/define-command.js';
3	import { Logger } from '../../logger.js';
4	import { DRAIN_TYPES, formatDrain, resolveDrainResource } from '../../models/drain.js';
5	import { sendToApi } from '../../models/send-to-api.js';
