13	export const drainCommand = defineCommand({
14	  description: 'Manage drains',
15	  since: '0.9.0',
16	  options: {
17	    alias: aliasOption,
18	    appIdOrName: appIdOrNameOption,
19	    addonIdOrRealId: addonIdOrRealIdOption,
20	    format: humanJsonOutputFormatOption,
21	  },
22	  args: [],
23	  async handler(options) {
24	    const { alias, appIdOrName, addonIdOrRealId, format } = options;
25	    const { ownerId, resourceId } = await resolveDrainResource(alias, appIdOrName, addonIdOrRealId);
26	
27	    const drains = await getDrains({ ownerId, resourceId }).then(sendToApi);
28	
29	    switch (format) {
30	      case 'json': {
31	        Logger.printJson(drains);
32	        break;
33	      }
34	      case 'human':
35	      default: {
36	        if (drains.length === 0) {
37	          const resourceLabel = addonIdOrRealId ?? appIdOrName?.app_id ?? appIdOrName?.app_name ?? alias ?? resourceId;
38	          Logger.println(`There are no drains for ${resourceLabel}`);
39	          return;
40	        }
41	
42	        if (drains.length === 1) {
43	          const formattedDrain = formatDrain(drains[0]);
44	          console.table(formattedDrain);
45	          return;
46	        }
47	
48	        const formattedDrains = drains.map((drain) => {
49	          return {
50	            ID: drain.id,
51	            Kind: drain.kind,
52	            Type: DRAIN_TYPES[drain.recipient.type]?.label ?? drain.recipient.type,
53	            Status: drain.status.status,
54	            'Execution status': drain.execution.status,
55	            URL: drain.recipient.url,
56	          };
57	        });
58	
59	        console.table(formattedDrains);
60	      }
61	    }
62	  },
63	});
